const form=document.querySelector('#labels'),status=document.querySelector('#status');
for(const entry of window.PANCAKE_CATALOG){const field=document.createElement('fieldset'),legend=document.createElement('legend');legend.textContent=entry.id;field.dataset.id=entry.id;field.append(legend);const image=document.createElement('img');image.src=entry.image||'assets/'+entry.kind+'-flat.svg';image.alt=(entry.displayName||entry.kind)+' pancake';field.append(image);for(const [key,title] of [['name','Contributor name'],['message','Supporting text']]){const label=document.createElement('label');label.textContent=title;const input=document.createElement('input');input.name=key;input.value=entry[key];input.maxLength=key==='name'?80:200;label.append(input);field.append(label)}form.append(field)}
function values(){return Object.fromEntries([...form.querySelectorAll('fieldset')].map(f=>[f.dataset.id,{name:f.querySelector('[name=name]').value.trim(),message:f.querySelector('[name=message]').value.trim()}]))}
function save(){try{localStorage.setItem('kodiak-labels-v1',JSON.stringify(values()));status.textContent='Preview saved in this browser. Open the canvas or stack to see it.';return true}catch{status.textContent='Browser storage is unavailable. Download the file to save your changes.';return false}}
document.querySelector('#preview').onclick=save;
document.querySelector('#download').onclick=()=>{const edits=values();const entries=window.PANCAKE_SOURCE.map(e=>({...e,...edits[e.id]}));const source='// Approved entries and saved sample placements. Shared by both views.\nwindow.SUBMISSIONS = '+JSON.stringify(entries,null,2)+';\n';const url=URL.createObjectURL(new Blob([source],{type:'text/javascript'}));const link=document.createElement('a');link.href=url;link.download='submissions.js';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);status.textContent='Replace dist/submissions.js with the downloaded file to save these labels in the project.'};
document.querySelector('#reset').onclick=()=>{try{localStorage.removeItem('kodiak-labels-v1');location.reload()}catch{status.textContent='Browser storage is unavailable.'}};
